const raw = ($json.output || '').toString();
let parsed = null;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parsed = null;
}

if (!parsed || typeof parsed !== 'object') {
  return [{ json: { parse_error: true, intent: 'other' } }];
}

return [{
  json: {
    parse_error: false,
    intent: parsed.intent || 'other',
    parent_search_term: parsed.parent_search_term || '',
    work_item_id: (parsed.work_item_id || '').toString().replace(/[^0-9]/g, ''),
    title: parsed.title || '',
    repro_steps: Array.isArray(parsed.repro_steps) ? parsed.repro_steps : [],
    expected_result: parsed.expected_result || '',
    actual_result: parsed.actual_result || '',
    evidence: parsed.evidence || '',
    environment: parsed.environment || '',
    priority: parsed.priority || '',
    severity: parsed.severity || '',
    area_path: parsed.area_path || '',
    iteration_path: parsed.iteration_path || '',
    assigned_to: parsed.assigned_to || '',
    state: parsed.state || '',
    comment: parsed.comment || ''
  }
}];

