parameters.jsCode:
const searchTerm = (($('Parse Extraction').item.json.parent_search_term) || '').toLowerCase().trim();
const items = ($json.value || []).map(v => ({
  id: v.id,
  title: (v.fields && v.fields['System.Title']) || '',
  type: (v.fields && v.fields['System.WorkItemType']) || ''
}));

function score(title) {
  const t = title.toLowerCase();
  if (!t) return 0;
  if (t === searchTerm) return 1;
  if (t.includes(searchTerm) || searchTerm.includes(t)) return 0.8;
  const aWords = new Set(searchTerm.split(/\s+/).filter(Boolean));
  const bWords = new Set(t.split(/\s+/).filter(Boolean));
  const inter = [...aWords].filter(w => bWords.has(w)).length;
  const union = new Set([...aWords, ...bWords]).size || 1;
  return inter / union;
}

const scored = items.map(it => ({ ...it, score: score(it.title) })).sort((a, b) => b.score - a.score);
const best = scored[0];
const second = scored[1];
const isResolved = !!(best && best.score >= 0.5 && (!second || (best.score - second.score) >= 0.15));

return [{
  json: {
    resolved: isResolved ? 'yes' : 'no',
    parent_id: isResolved ? best.id : '',
    candidates: scored
  }
}];

