const newTitle = (($('Parse Extraction').item.json.title) || '').toLowerCase();
const items = ($json.value || []).map(v => ({ id: v.id, title: (v.fields && v.fields['System.Title']) || '' }));

function jaccard(a, b) {
  const aw = new Set(a.split(/\s+/).filter(Boolean));
  const bw = new Set(b.toLowerCase().split(/\s+/).filter(Boolean));
  const inter = [...aw].filter(w => bw.has(w)).length;
  const union = new Set([...aw, ...bw]).size || 1;
  return inter / union;
}

let best = null;
for (const it of items) {
  const s = jaccard(newTitle, it.title);
  if (!best || s > best.score) best = { ...it, score: s };
}

const duplicateFound = !!(best && best.score >= 0.45);

return [{ json: { duplicate_found: duplicateFound ? 'yes' : 'no', duplicate_match: best } }];

const d = $('Parse Extraction').item.json;
const steps = (d.repro_steps || []).map((s, i) => `${i + 1}. ${s}`).join('<br>');
const description =
  `<b>Bug description:</b> ${d.title}<br><br>` +
  `<b>Steps to reproduce:</b><br>${steps || 'Not provided'}<br><br>` +
  `<b>Expected result:</b> ${d.expected_result || 'Not provided'}<br><br>` +
  `<b>Actual result:</b> ${d.actual_result || 'Not provided'}<br><br>` +
  `<b>Evidence:</b> ${d.evidence || 'Not provided'}<br><br>` +
  `<b>Environment:</b> ${d.environment || 'Not provided'}`;

const parentId = $('Resolve Parent').item.json.parent_id;
const title = `[Bug] - ${d.title}`;

const ops = [
  { op: 'add', path: '/fields/System.Title', value: title },
  { op: 'add', path: '/fields/Microsoft.VSTS.TCM.ReproSteps', value: description },
  { op: 'add', path: '/relations/-', value: { rel: 'System.LinkTypes.Hierarchy-Reverse', url: `https://dev.azure.com/${$env.ADO_ORG}/${$env.ADO_PROJECT}/_apis/wit/workItems/${parentId}` } }
];
if (d.priority) ops.push({ op: 'add', path: '/fields/Microsoft.VSTS.Common.Priority', value: d.priority });
if (d.severity) ops.push({ op: 'add', path: '/fields/Microsoft.VSTS.Common.Severity', value: d.severity });
if (d.area_path) ops.push({ op: 'add', path: '/fields/System.AreaPath', value: d.area_path });
if (d.iteration_path) ops.push({ op: 'add', path: '/fields/System.IterationPath', value: d.iteration_path });
if (d.assigned_to) ops.push({ op: 'add', path: '/fields/System.AssignedTo', value: d.assigned_to });

return [{ json: { ops, parent_id: parentId, title } }];

const resp = $json;
const parentId = $('Build Bug Payload').item.json.parent_id;
const title = $('Build Bug Payload').item.json.title;

if (resp && typeof resp.id === 'number') {
  return [{ json: { output: `Bug #${resp.id} created and linked to Parent #${parentId}.\nTitle: ${title}` } }];
}

return [{ json: { output: `I couldn't create the bug automatically - Azure DevOps returned: ${JSON.stringify(resp).slice(0, 500)}` } }];

