}

const header = '| ID | Title | Type | State |\n|---|---|---|---|';
const rows = items.map(it => `| ${it.id} | ${it.title} | ${it.type} | ${it.state} |`).join('\n');

return [{ json: { output: `Work items linked to #${parentId}:\n\n${header}\n${rows}` } }];

const resp = $json;
const d = $('Parse Extraction').item.json;

if (resp && typeof resp.id === 'number') {
  const parts = [`Work item #${resp.id} updated.`];
  if (d.state) parts.push(`New state: ${d.state}.`);
  if (d.comment) parts.push('Comment added.');
  return [{ json: { output: parts.join(' ') } }];
}

return [{ json: { output: `I couldn't update work item #${d.work_item_id} - Azure DevOps returned: ${JSON.stringify(resp).slice(0, 500)}` } }];

